function bind(){const form=document.getElementById('assessment-form');if(form?.elements?.destination){const sync=()=>{const d=form.elements.destination,r=form.elements.route,allowed={ausbildung:['germany'],professional:['germany','norway'],resume:['germany','norway','japan','romania','serbia'], 'japan-language':['japan'],'japan-skills':['japan'],'job-search':['romania','serbia']};for(const option of r.options){const countries=allowed[option.value];option.disabled=!!countries&&!!d.value&&d.value!=='unsure'&&!countries.includes(d.value);}if(r.selectedOptions[0]?.disabled)r.value='';};form.elements.destination.onchange=sync;form.elements.route.onchange=()=>{if(form.elements.route.value==='ausbildung')form.elements.destination.value='germany';if(['japan-language','japan-skills'].includes(form.elements.route.value))form.elements.destination.value='japan';sync()};}document.querySelectorAll('[data-lang]').forEach(el=>el.onclick=()=>{const v=el.dataset.lang;const url=new URL(location.href);url.searchParams.set('lang',v);history.replaceState({},'',url);try{localStorage.setItem('moshir-language',v)}catch{}render(v);document.querySelector(`[data-lang="${v}"]`).focus()});const m=document.querySelector('.menu'),n=document.querySelector('.nav');m.onclick=()=>{m.setAttribute('aria-expanded',String(n.classList.toggle('open')))};n.querySelectorAll('a').forEach(a=>a.onclick=()=>{n.classList.remove('open');m.setAttribute('aria-expanded','false')});document.querySelectorAll('[data-modal]').forEach(a=>a.onclick=e=>{e.preventDefault();openModal(a.dataset.modal)});document.querySelectorAll('[data-service]').forEach(a=>a.onclick=()=>openModal('service',+a.dataset.service));document.getElementById('assessment-form').onsubmit=e=>{e.preventDefault();summaryReady=true;showSummary()};document.querySelector('.share-link').onclick=async()=>{const u=new URL(location.href);u.hash='';u.searchParams.set('lang',lang);try{await navigator.clipboard.writeText(u.href);toast(copy[lang].copied)}catch{toast(copy[lang].copyFail)}};}
function showSummary(){document.getElementById('form-result').textContent=copy[lang].result;const b=document.getElementById('download-summary');b.hidden=false;b.onclick=()=>{const c=copy[lang],f=document.getElementById('assessment-form');const file=f.elements.cv.files[0];const lines=[c.snapshot,'',c.name+': '+f.elements.fullname.value,c.contact+': '+f.elements.contact.value,c.destination+': '+f.elements.destination.selectedOptions[0].textContent,c.route+': '+f.elements.route.selectedOptions[0].textContent,c.fileSelected+': '+(file?file.name:c.noFile),'',c.result];const url=URL.createObjectURL(new Blob(['\uFEFF'+lines.join('\n')],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='moshir-enquiry-'+lang+'.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);};}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('visible');setTimeout(()=>t.classList.remove('visible'),6000)}
function openModal(key,index){const c=copy[lang],d=document.getElementById('info');lastFocus=document.activeElement;document.getElementById('dialog-close').setAttribute('aria-label',c.close);const v=key==='service'?[c.services[index][0],c.services[index][2]]:c.modal[key];const el=document.getElementById('dialog-content');el.replaceChildren();const h=document.createElement('h2'),p=document.createElement('p');h.id='dialog-title';h.textContent=v[0];p.textContent=v[1];el.append(h,p);if(key==='service'){const b=document.createElement('button');b.className='btn coral';b.textContent=c.selectRoute;b.onclick=()=>{document.getElementById('route').value=ids[index];d.close();document.getElementById('assessment').scrollIntoView({behavior:'smooth'});document.querySelector('[name="fullname"]').focus({preventScroll:true})};el.append(b)}d.showModal()}
document.getElementById('dialog-close').onclick=()=>document.getElementById('info').close();document.getElementById('info').addEventListener('close',()=>lastFocus?.isConnected&&lastFocus.focus());document.getElementById('info').addEventListener('click',e=>{const d=e.currentTarget,r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close()});render(initialLanguage());
